<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { adminAlbums, saveAlbum, albumStatus } from '../../api/admin'
import PageTitle from '../../components/PageTitle.vue'
const rows=ref([]),loading=ref(false),keyword=ref(''),dialog=ref(false),editId=ref(null),formRef=ref(),page=ref(1),total=ref(0),form=reactive({title:'',artist:'',coverUrl:'',description:'',productType:'PHYSICAL',digitalContentUrl:'',releaseDate:'',price:'',stock:0,status:1,isLimited:0});const rules={title:[{required:true,message:'请输入专辑名称'}],artist:[{required:true,message:'请输入艺人名称'}],price:[{required:true,message:'请输入价格'}],stock:[{required:true,message:'请输入库存'}]}
async function load(){loading.value=true;try{const p=await adminAlbums({current:page.value,size:10,keyword:keyword.value||undefined});rows.value=p?.records||[];total.value=Number(p?.total||0)}finally{loading.value=false}}
function open(row){editId.value=row?.id||null;Object.assign(form,row?{...row}:{title:'',artist:'',coverUrl:'',description:'',productType:'PHYSICAL',digitalContentUrl:'',releaseDate:'',price:'',stock:0,status:1,isLimited:0});dialog.value=true}
async function save(){await formRef.value.validate();await saveAlbum(editId.value,{...form,price:Number(form.price),stock:Number(form.stock),status:Number(form.status),isLimited:Number(form.isLimited),releaseDate:form.releaseDate||null,coverUrl:form.coverUrl||null,digitalContentUrl:form.digitalContentUrl||null,description:form.description||null});ElMessage.success('专辑已保存');dialog.value=false;load()}
async function toggle(row){await albumStatus(row.id,Number(row.status)===1?0:1);ElMessage.success('状态已更新');load()}
onMounted(load)
</script>
<template><div class="admin-page"><PageTitle eyebrow="CATALOGUE" title="专辑管理"/><div class="toolbar"><el-input v-model="keyword" placeholder="按专辑名称搜索" clearable style="max-width:300px" @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">搜索</el-button><el-button type="primary" @click="open()">新增专辑</el-button></div><el-table v-loading="loading" :data="rows"><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="title" label="专辑" min-width="180"/><el-table-column prop="artist" label="艺人" min-width="120"/><el-table-column prop="productType" label="形态" width="110"/><el-table-column prop="price" label="价格" width="90"/><el-table-column prop="stock" label="库存" width="80"/><el-table-column prop="status" label="状态" width="90"><template #default="{row}">{{Number(row.status)===1?'上架':'下架'}}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button text @click="open(row)">编辑</el-button><el-button text @click="toggle(row)">{{Number(row.status)===1?'下架':'上架'}}</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" :page-size="10" :total="total" layout="prev,pager,next" @current-change="load"/></div><el-dialog v-model="dialog" :title="editId?'编辑专辑':'创建专辑'" width="min(760px,94vw)"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><div class="form-grid"><el-form-item label="专辑名称" prop="title"><el-input v-model="form.title"/></el-form-item><el-form-item label="艺人" prop="artist"><el-input v-model="form.artist"/></el-form-item><el-form-item label="商品形态"><el-select v-model="form.productType"><el-option label="实体商品" value="PHYSICAL"/><el-option label="数字专辑" value="DIGITAL"/></el-select></el-form-item><el-form-item label="价格" prop="price"><el-input v-model="form.price" type="number"/></el-form-item><el-form-item label="库存" prop="stock"><el-input v-model="form.stock" type="number"/></el-form-item><el-form-item label="发行日期"><el-date-picker v-model="form.releaseDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="封面 URL" class="span-2"><el-input v-model="form.coverUrl"/></el-form-item><el-form-item v-if="form.productType==='DIGITAL'" label="HTTPS 数字内容地址" class="span-2"><el-input v-model="form.digitalContentUrl"/></el-form-item><el-form-item label="简介" class="span-2"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="上架状态"><el-select v-model="form.status"><el-option label="上架" :value="1"/><el-option label="下架" :value="0"/></el-select></el-form-item><el-form-item label="限量"><el-select v-model="form.isLimited"><el-option label="否" :value="0"/><el-option label="是" :value="1"/></el-select></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
